export const SPEED = 2; // units per second along the arc length

// Six inline waypoints defining a closed city loop.
const DEFAULT_WAYPOINTS = [
  new THREE.Vector3(30, 0, 0),
  new THREE.Vector3(20, 0, 18),
  new THREE.Vector3(0, 0, 26),
  new THREE.Vector3(-22, 0, 16),
  new THREE.Vector3(-28, 0, -8),
  new THREE.Vector3(4, 0, -24),
];

/**
 * Builds the smart-city hero road: a closed Catmull-Rom spline through six
 * waypoints plus a flattened TubeGeometry mesh used as the visible road ribbon.
 */
export function buildRoad(points) {
  const waypoints =
    Array.isArray(points) && points.length >= 2 ? points : DEFAULT_WAYPOINTS;

  const curve = new THREE.CatmullRomCurve3(waypoints, true, 'catmullrom', 0.5);

  // Tube swept along the loop, flattened on Y so it reads as a road surface.
  const geometry = new THREE.TubeGeometry(curve, 256, 3, 12, true);
  geometry.scale(1, 0.05, 1);

  const material = new THREE.MeshStandardMaterial({
    color: 0x2b2f33,
    roughness: 0.95,
    metalness: 0,
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'road';

  return { curve, mesh };
}

const _target = new THREE.Vector3();
const _tangent = new THREE.Vector3();

/** Places a car on the curve at arc-length fraction `u`, facing along the tangent. */
function pose(car, curve, u) {
  curve.getPointAt(u % 1, car.position);
  curve.getTangentAt(u % 1, _tangent);
  _target.copy(car.position).add(_tangent);
  car.up.set(0, 1, 0);
  car.lookAt(_target);
}

/**
 * Spawns `n` box cars at equal arc-length fractions of the closed curve
 * (u = i/n via getPointAt) and returns the shared traffic state.
 */
export function spawnCars(curve, n) {
  const length = curve.getLength();
  const cars = [];
  const geometry = new THREE.BoxGeometry(1.2, 0.8, 2.4);
  const material = new THREE.MeshStandardMaterial({
    color: 0xff5533,
    roughness: 0.6,
  });

  for (let i = 0; i < n; i++) {
    const car = new THREE.Mesh(geometry, material);
    car.name = `car-${i}`;
    // Lift slightly so the box sits on top of the flattened road ribbon.
    car.position.y += 0.6;
    pose(car, curve, i / n);
    cars.push(car);
  }

  return { curve, length, offset: 0, cars };
}

/** Arc-length fraction of car `i` given the shared offset. */
export function carU(state, i) {
  const n = state.cars.length;
  return ((((i / n) * state.length + state.offset) / state.length) % 1 + 1) % 1;
}

/**
 * Advances the shared arc-length offset at SPEED units/sec (wrapping at the
 * total curve length) and re-poses every car via getPointAt + tangent heading.
 */
export function stepTraffic(state, dt) {
  state.offset = (((state.offset + SPEED * dt) % state.length) + state.length) % state.length;

  for (let i = 0; i < state.cars.length; i++) {
    pose(state.cars[i], state.curve, carU(state, i));
  }

  return state;
}
"})
