result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/traffic.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildRoad, spawnCars, stepTraffic, SPEED } from '../src/traffic.js';

// --- helpers ---------------------------------------------------------------

const SAMPLES = 2048;

/** Pre-sample the curve by arc length for coarse localization. */
function sampleCurve(curve) {
  const pts = [];
  for (let i = 0; i < SAMPLES; i++) pts.push(curve.getPointAt(i / SAMPLES));
  return pts;
}

/**
 * Recover the arc-length fraction u of a world point on the curve:
 * coarse nearest-sample scan followed by Newton refinement of
 * g(u) = (P(u) - X) . T(u) = 0. Independent of the traffic state.
 */
function recoverU(curve, samples, point) {
  let best = 0;
  let bestDist = Infinity;
  for (let i = 0; i < SAMPLES; i++) {
    const d = samples[i].distanceToSquared(point);
    if (d < bestDist) {
      bestDist = d;
      best = i;
    }
  }

  let u = best / SAMPLES;
  const length = curve.getLength();
  const p = new THREE.Vector3();
  const t = new THREE.Vector3();
  for (let iter = 0; iter < 20; iter++) {
    curve.getPointAt(u % 1, p);
    curve.getTangentAt(u % 1, t);
    const g = p.sub(point).dot(t);
    // dP/du has magnitude `length`; the tangent term dominates near the root.
    const step = THREE.MathUtils.clamp(g / length, -1 / SAMPLES, 1 / SAMPLES);
    u -= step;
    if (Math.abs(step) < 1e-15) break;
  }
  return ((u % 1) + 1) % 1;
}

function forwardAxis(car) {
  return new THREE.Vector3(0, 0, 1).applyQuaternion(car.quaternion);
}

// --- tests -----------------------------------------------------------------

describe('traffic loop', () => {
  const { curve } = buildRoad();
  const totalLength = curve.getLength();

  it('builds a closed road curve with positive length', () => {
    expect(totalLength).toBeGreaterThan(0);
    expect(curve.getPoint(0).distanceTo(curve.getPoint(1))).toBeLessThan(1e-9);
  });

  it('keeps consecutive cars at constant arc-length separation over 200 steps', () => {
    const n = 5;
    const state = spawnCars(curve, n);
    const samples = sampleCurve(curve);
    const dt = 0.05;

    let initialSep = null;
    for (let step = 0; step <= 200; step++) {
      if (step > 0) stepTraffic(state, dt);

      const us = state.cars.map((car) => recoverU(curve, samples, car.position));
      const seps = [];
      for (let i = 0; i < n; i++) {
        const next = us[(i + 1) % n];
        seps.push((((next - us[i]) % 1) + 1) % 1 * totalLength);
      }

      if (initialSep === null) {
        initialSep = seps[0];
        // Equal fractions -> equal spacing of totalLength / n.
        expect(initialSep).toBeCloseTo(totalLength / n, 6);
      } else {
        for (const sep of seps) {
          expect(Math.abs(sep - initialSep)).toBeLessThan(1e-6);
        }
      }
    }
  });

  it('keeps every car exactly on the curve', () => {
    const state = spawnCars(curve, 5);
    const samples = sampleCurve(curve);
    stepTraffic(state, 0.37);
    stepTraffic(state, 1.13);

    for (const car of state.cars) {
      const u = recoverU(curve, samples, car.position);
      const onCurve = curve.getPointAt(u);
      expect(car.position.distanceTo(onCurve)).toBeLessThan(1e-9);
    }
  });

  it('after totalLength/2 seconds each car occupies its successor start position', () => {
    const n = 7; // odd count avoids degenerate symmetric aliasing
    const state = spawnCars(curve, n);
    const startPositions = state.cars.map((c) => c.position.clone());

    const dt = 0.02;
    const totalTime = totalLength / SPEED / 2; // advance half the loop
    let remaining = totalTime;
    while (remaining > 0) {
      const h = Math.min(dt, remaining);
      stepTraffic(state, h);
      remaining -= h;
    }

    for (let i = 0; i < n; i++) {
      const successorStart = startPositions[(i + 1) % n];
      expect(state.cars[i].position.distanceTo(successorStart)).toBeLessThan(1e-3);
    }
  });

  it('orients every car heading along the curve tangent', () => {
    const state = spawnCars(curve, 5);
    stepTraffic(state, 0.61);
    stepTraffic(state, 2.4);

    const t = new THREE.Vector3();
    state.cars.forEach((car) => {
      const u = ((((state.cars.indexOf(car)) / state.cars.length) * state.length + state.offset) / state.length) % 1;
      curve.getTangentAt(u, t);
      const angle = forwardAxis(car).angleTo(t);
      expect(angle).toBeLessThan(1e-3);
    });
  });
});
"})
